"""The README's catalog section is generated by scripts/catalog_table.py and must match the shipped catalog."""

import importlib.util
import re
from collections import Counter
from pathlib import Path

from sysadmin import catalog, ops  # noqa: F401

ROOT = Path(__file__).resolve().parent.parent
README = (ROOT / "README.md").read_text(encoding="utf-8")


def _table_module():
    spec = importlib.util.spec_from_file_location("catalog_table", ROOT / "scripts" / "catalog_table.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_readme_has_every_category_heading_with_the_right_count():
    counts = Counter(op.meta["category"] for op in catalog.entries())
    assert counts, "catalog is empty"
    for cat, n in counts.items():
        assert f"#### {cat} ({n})" in README, f"README is missing '{cat} ({n})'"
    headings = re.findall(r"^#### (.+) \((\d+)\)$", README, re.M)
    assert {h: int(c) for h, c in headings} == dict(counts)


def test_readme_catalog_block_is_up_to_date_and_states_total():
    mod = _table_module()
    assert mod.block() in README, "README catalog block is stale; run scripts/catalog_table.py --write-readme"
    assert f"{len(catalog.entries())} vetted" in README


def test_readme_documents_empty_module_lock():
    assert "no gallery modules ship" in README.lower().replace("\n", " ")
